def data(
    token: str | None = None,
    base_url: str | None = None,
    **options,
) -> SmsapiData:
    """Build a SmsapiData client, finding credentials automatically.

    Discovery order (first hit wins):
      1. the `token` / `base_url` arguments
      2. Colab secrets  — SMSAPI_APIKEY / SMSAPI_BASE
      3. environment    — SMSAPI_APIKEY / SMSAPI_BASE

    Extra keyword arguments are passed straight through to the SDK client, so
    anything the SDK accepts (feature options, headers, timeouts) works here.
    """
    token, base_url, _source = auth.resolve("SMSAPI", token, base_url)

    if not token:
        raise ValueError(auth.missing_token_message("SMSAPI"))

    opts: dict = {"apikey": token}
    if base_url:
        opts["base"] = base_url
    opts.update(options)

    return SmsapiData(SmsapiSDK(opts), base_url)
